/**
 * Authorization Information Store (Community Edition)
 *
 * This file is generated by the publish pipeline (scripts/publish_community.py):
 * The community version has no authorization system. This stub maintains the same public interface as the stores/license.ts of the Pro version.
 * Zero changes on the consumer side (Dashboard/UserProfile/featureAccess/Learning/DataImport/TradeReview).
 *
 * Behavioral semantics:
 * - Does not initiate any network requests (no /api/license/status detection, community version does not have this route)
 * - isPro is always false, plan is always 'free'
 * - hasFeature Free features only (aligned with backend community_stub FREE_ACCESS_FEATURES)
 */

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'

// Authorization information interface (consistent with Pro version)
export interface LicenseInfo {
  email: string
  plan: 'free' | 'trial' | 'pro' | 'enterprise'
  features: string[]
  auth_server?: string
  auth_server_options?: Array<{ value: string; label: string }>
  device_registered: boolean
  is_valid: boolean
  error_message?: string
  verified_at?: string
  trial_end_at?: string
  pro_expire_at?: string
  offline_mode?: boolean
}

// Advanced student feature list (consistent with Pro version, only as a source of types and enumerations)
export const PRO_FEATURES = [
  'advanced_courses',
  'email_notification',
  'watchlist_groups',
  'scheduled_analysis',
  'portfolio_analysis',
  'trade_review',
  'batch_analysis',
  'export_reports',
  'trading_plan_check',
  'workflow',
  'workflow_tools',
  'workflow_agents',
  'prompt_templates',
] as const

export type ProFeature = typeof PRO_FEATURES[number]

// Community version free release function (aligned with core/licensing/community_stub.py FREE_ACCESS_FEATURES)
const FREE_ACCESS_FEATURES = new Set<ProFeature>([
  'portfolio_analysis',
  'trade_review'
])

// Community version fixed licensing information (Free file)
const COMMUNITY_LICENSE_INFO: LicenseInfo = {
  email: '',
  plan: 'free',
  features: ['portfolio_analysis', 'trade_review'],
  device_registered: false,
  is_valid: true,
  offline_mode: false
}

export const useLicenseStore = defineStore('license', () => {
  // Status (retaining interface compatibility; licenseInfo is fixed to Free file, not from the network)
  const appToken = ref<string | null>(localStorage.getItem('app-token'))
  const licenseInfo = ref<LicenseInfo | null>({ ...COMMUNITY_LICENSE_INFO })
  const loading = ref(false)
  const error = ref<string | null>(null)
  const lastVerifiedAt = ref<Date | null>(null)

  // Computed Properties: Community Edition Constant Value
  const isPro = computed(() => false)
  const isEnterprise = computed(() => false)
  const isTrial = computed(() => false)
  // The type remains consistent with the Pro version (complete union type), and the runtime value is always 'free', 
  // consumer side plan === 'pro' Wait until the branch type is legal (never hit during runtime, use free as a cover)
  const plan = computed((): LicenseInfo['plan'] => 'free')

  const expireAt = computed(() => null)
  const daysRemaining = computed(() => null)
  const isExpiringSoon = computed(() => false)
  const isExpired = computed(() => false)
  const isOffline = computed(() => false)
  const hasLegacyCourseAccess = computed(() => false)

  const hasFeature = (_feature: ProFeature) => {
    return FREE_ACCESS_FEATURES.has(_feature)
  }

  // Actions: Local no-op, no network request is sent
  const setAppToken = async (token: string) => {
    appToken.value = token
    localStorage.setItem('app-token', token)
  }

  const clearAppToken = () => {
    appToken.value = null
    licenseInfo.value = { ...COMMUNITY_LICENSE_INFO }
    localStorage.removeItem('app-token')
  }

  const verifyLicense = async (_force = false, _authServer?: string): Promise<boolean> => {
    // The community version has no authorization system: directly returns the Free file valid status without initiating a request.
    lastVerifiedAt.value = new Date()
    return true
  }

  // The community version does not require initialization verification (no request is sent)

  return {
    // State
    appToken,
    licenseInfo,
    loading,
    error,
    // Getters
    isPro,
    isEnterprise,
    isTrial,
    plan,
    expireAt,
    daysRemaining,
    isExpiringSoon,
    isExpired,
    isOffline,
    hasLegacyCourseAccess,
    hasFeature,
    // Actions
    setAppToken,
    clearAppToken,
    verifyLicense
  }
})
